-- ============================================
-- LUMA — Thème 7 : LONG 2/3 x4 — Un litige avec le service client
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent 1", "agent2": "l''agent 2 (escalade)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Your package was marked ''delivered'' three days ago, but it never arrived.)", "text_fr": "(Votre colis a été marqué ''livré'' il y a trois jours, mais il n''est jamais arrivé.)", "choices": [{"text": "(Start a live chat with customer service.)", "text_fr": "(Démarre un chat en direct avec le service client.)", "next": "n2"}, {"text": "(Call customer service directly.)", "text_fr": "(Appelle directement le service client.)", "next": "n2b"}]}, "n2": {"speaker": "agent", "text": "Hi there! How can I help you today?", "text_fr": "Bonjour ! Comment puis-je vous aider aujourd''hui ?", "choices": [{"text": "My order shows as delivered, but I never received it.", "text_fr": "Ma commande est marquée comme livrée, mais je ne l''ai jamais reçue.", "next": "n3"}]}, "n2b": {"speaker": "agent", "text": "Thank you for calling, what seems to be the issue?", "text_fr": "Merci d''appeler, quel est le problème ?", "choices": [{"text": "My package says delivered three days ago but it''s not here.", "text_fr": "Mon colis est marqué livré il y a trois jours mais il n''est pas là.", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "I''m sorry to hear that. Let me look into this for you — can I get your order number?", "text_fr": "Je suis désolé d''entendre ça. Laissez-moi vérifier ça pour vous — je peux avoir votre numéro de commande ?", "choices": [{"text": "Sure, it''s #48291.", "text_fr": "Bien sûr, c''est le #48291.", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "Thank you. I see it was marked delivered, but there''s no signature on file.", "text_fr": "Merci. Je vois qu''il a été marqué livré, mais il n''y a pas de signature enregistrée.", "choices": [{"text": "That''s strange, could it have been left at the wrong address?", "text_fr": "C''est étrange, il aurait pu être laissé à la mauvaise adresse ?", "next": "n5"}, {"text": "Could you check with the carrier directly about this?", "text_fr": "Vous pourriez vérifier directement avec le transporteur ?", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "That''s possible. Let me open an investigation with the carrier.", "text_fr": "C''est possible. Laissez-moi ouvrir une enquête avec le transporteur.", "choices": [{"text": "Thank you, how long does that usually take?", "text_fr": "Merci, combien de temps ça prend généralement ?", "next": "n6"}]}, "n6": {"speaker": "agent", "text": "Usually 3-5 business days. I''ll email you updates as they come in.", "text_fr": "Généralement 3-5 jours ouvrables. Je vous enverrai des mises à jour au fur et à mesure.", "choices": [{"text": "Okay, thank you for looking into it.", "text_fr": "D''accord, merci de vous en occuper.", "next": "n7"}, {"text": "That feels like a long wait, is there anything faster you can do?", "text_fr": "Ça semble être une longue attente, il y a quelque chose de plus rapide que vous pouvez faire ?", "next": "n7b"}]}, "n7": {"speaker": "you_thought", "text": "(Five days later, you follow up since you haven''t heard anything.)", "text_fr": "(Cinq jours plus tard, vous relancez car vous n''avez rien entendu.)", "choices": [{"text": "(Contact customer service again for an update.)", "text_fr": "(Contacte encore le service client pour une mise à jour.)", "next": "n8"}]}, "n7b": {"speaker": "agent", "text": "I understand the frustration — let me escalate this to our priority team.", "text_fr": "Je comprends la frustration — laissez-moi escalader ça à notre équipe prioritaire.", "choices": [{"text": "Thank you, I appreciate you taking this seriously.", "text_fr": "Merci, j''apprécie que vous preniez ça au sérieux.", "next": "n8"}]}, "n8": {"speaker": "agent2", "text": "I see there''s an open case for you. Let me check the latest status.", "text_fr": "Je vois qu''il y a un dossier ouvert pour vous. Laissez-moi vérifier le dernier statut.", "choices": [{"text": "Thank you, I really hope there''s some progress.", "text_fr": "Merci, j''espère vraiment qu''il y a du progrès.", "next": "n9"}]}, "n9": {"speaker": "agent2", "text": "Unfortunately, the carrier confirms the package is lost. I''m very sorry about this.", "text_fr": "Malheureusement, le transporteur confirme que le colis est perdu. Je suis vraiment désolé pour ça.", "choices": [{"text": "That''s frustrating, but I appreciate you confirming. What happens now?", "text_fr": "C''est frustrant, mais j''apprécie la confirmation. Qu''est-ce qui se passe maintenant ?", "next": "n10"}, {"text": "This has been a really disappointing experience, honestly.", "text_fr": "Ça a été une expérience vraiment décevante, honnêtement.", "next": "n10b"}]}, "n10": {"speaker": "agent2", "text": "We''ll issue a full refund, or we can send a replacement — your choice.", "text_fr": "On va émettre un remboursement complet, ou on peut envoyer un remplacement — à vous de choisir.", "choices": [{"text": "A replacement would be great, if it can ship quickly.", "text_fr": "Un remplacement serait super, si ça peut être expédié rapidement.", "next": "n11"}, {"text": "I''d prefer a refund at this point, honestly.", "text_fr": "Je préférerais un remboursement à ce stade, honnêtement.", "next": "n11"}]}, "n10b": {"speaker": "agent2", "text": "I completely understand, and I want to make this right for you.", "text_fr": "Je comprends totalement, et je veux arranger ça pour vous.", "choices": [{"text": "I appreciate that — a replacement or refund would help a lot.", "text_fr": "J''apprécie — un remplacement ou remboursement aiderait beaucoup.", "next": "n11"}]}, "n11": {"speaker": "agent2", "text": "Done — and I''ve added a discount code for the inconvenience as well.", "text_fr": "C''est fait — et j''ai aussi ajouté un code de réduction pour le désagrément.", "choices": [{"text": "Thank you, that really helps make up for the trouble.", "text_fr": "Merci, ça aide vraiment à compenser le désagrément.", "next": "n12"}]}, "n12": {"speaker": "agent2", "text": "You''re very welcome. Thank you for your patience through this whole process.", "text_fr": "Je vous en prie. Merci pour votre patience à travers tout ce processus.", "choices": [{"text": "I appreciate you seeing it through to a good resolution.", "text_fr": "J''apprécie que vous ayez mené ça à une bonne résolution.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "agent2", "text": "That''s what we''re here for. Have a wonderful day!", "text_fr": "C''est pour ça qu''on est là. Passez une merveilleuse journée !", "end": true, "ending_label": "Litige résolu après plusieurs escalades 📦✅"}}}'::jsonb, is_playable = true
where title = 'Un litige avec le service client'
  and theme_id = (select id from scenario_themes where position = 7 and language_id = (select id from languages where code = 'en'));
